def check_summary():
    """Verify report.py exists, out/summary.json exists, and its contents are correct (independent recompute)."""
    import json, os, csv
    ok = []
    if not os.path.exists("report.py"):
        return "FAIL: report.py missing"
    if not os.path.exists("out/summary.json"):
        return "FAIL: out/summary.json missing"
    data = json.load(open("out/summary.json"))
    # recompute expected values independently
    from collections import defaultdict
    rev = defaultdict(float)
    units = defaultdict(int)
    skipped = 0
    for row in csv.DictReader(open("data/sales.csv")):
        u = (row.get("units") or "").strip()
        try:
            uni = int(float(u)) if u else None
        except ValueError:
            uni = None
        if uni is None or uni < 0:
            skipped += 1
            continue
        region = (row.get("region") or "").strip().lower()
        price = float(row.get("unit_price") or 0)
        rev[region] += uni * price
        units[row["product"]] += uni
    expected = {
        "revenue_by_region": {k: round(v, 2) for k, v in sorted(rev.items())},
        "top_product": max(units.items(), key=lambda kv: kv[1])[0],
        "skipped_rows": skipped,
    }
    if data.get("revenue_by_region") != expected["revenue_by_region"]:
        ok.append(f"revenue mismatch: got {data.get('revenue_by_region')} want {expected['revenue_by_region']}")
    if data.get("top_product") != expected["top_product"]:
        ok.append(f"top_product mismatch: got {data.get('top_product')} want {expected['top_product']}")
    if data.get("skipped_rows") != expected["skipped_rows"]:
        ok.append(f"skipped mismatch: got {data.get('skipped_rows')} want {expected['skipped_rows']}")
    if len(data) != 3:
        ok.append(f"extra/missing keys: {sorted(data.keys())}")
    return "PASS" if not ok else "FAIL: " + " | ".join(ok)

